#include "polyec/realm.hpp"
#include <algorithm>
#include <iostream>
#include <stdexcept>
using namespace polyec;
int n=0;void test(bool b,const char*s){++n;if(!b)throw std::runtime_error(s);}
Realm fixture(int card,bool activate=true){for(int seed=1;seed<2000;++seed){Realm w(seed,6,256);auto d=w.draft();if(std::find(d.cards.begin(),d.cards.end(),card)!=d.cards.end()){if(activate)test(w.choose(card),"choose known augment");return w;}}throw std::runtime_error("draft coverage");}
void act(Realm&w,uint64_t id,Candidate c){test(w.execute({id,w.person(id).decisions+1,c}).success,"court action commits");test(w.invariant(),"court ledger reconciles");}
void roundtrip(Realm&w){std::string error;Realm r(1,1,128);test(r.deserialize(w.serialize("court"),"court",error),"court save parses");test(r.fingerprint()==w.fingerprint(),"court save exact");w.advance(7);r.advance(7);test(r.fingerprint()==w.fingerprint(),"court continuation exact");}
int main(){try{
for(int card=0;card<12;++card){auto w=fixture(card);test(w.invariant(),"opening court ledger");auto region=w.person(1).region;auto total=w.total_money();
 if(card==0||card==7){auto plain=fixture(card,false);test(w.observation(1)[105]<plain.observation(1)[105],"augment reduces public report latency against identical opening");auto before=w.view().facts.size();w.advance(30);bool inventory=false;for(auto&f:w.view().facts)inventory|=f.kind==108;test(!inventory,"inventory report has genuine delay");w.advance(12);for(auto&f:w.view().facts)inventory|=f.kind==108;test(inventory,"inventory report delivered");(void)before;}
 if(card==1||card==10){uint64_t teacher=0;for(uint64_t id=15;id<=256;++id){auto&p=w.person(id);if(p.family==Family::Civilian&&p.region==region&&p.age_days>=18*365&&p.skill>=20){teacher=id;break;}}test(teacher>0,"existing teacher");act(w,teacher,{Intent::Work,region,0,0,30});test(w.person(teacher).job_kind==1&&w.job_type(teacher)==JobType::Teacher&&w.view().provinces[region].teachers==1,"teacher starts with a daily counter");act(w,1,{Intent::Project,region,card==1?2:3,120,60});auto plain=fixture(card,false);act(plain,teacher,{Intent::Work,region,0,0,30});act(plain,1,{Intent::Project,region,card==1?2:3,120,60});test(w.projects().back().due<plain.projects().back().due,"specialized training improves identical funded project");if(card==10){act(w,1,{Intent::Project,region,3,120,60});auto before=w.fingerprint();test(!w.execute({1,w.person(1).decisions+1,{Intent::Project,region,3,120,60}}).success&&before==w.fingerprint(),"third teacher course rejected atomically");}}
 if(card==2){act(w,1,w.candidates(1)[14]);act(w,1,w.candidates(1)[22]);test(w.mask(1)[22]==0,"mediation cooldown");w.advance(12);act(w,2,w.candidates(2)[29]);}
 if(card==3){test(w.view().provinces[region].food_capacity>w.view().provinces[region].residents*10,"three month capacity");}
 if(card==4){test(w.royal_reference()>0&&w.royal_funds()[0]==w.royal_reference()/2,"reference-funded credit offer");auto c=w.candidates(1)[17];if(c.amount>0){auto pool=w.royal_funds()[0];act(w,1,c);test(w.loans().back().royal_pool&&w.loans().back().due==1825&&w.royal_funds()[0]==pool-c.amount,"five year pool debt");act(w,1,{Intent::Repay,region,0,c.amount});test(w.royal_funds()[0]==pool,"repayment to creditor pool");}}
 if(card==5){act(w,1,{Intent::Project,region,0,200,60});test(w.projects().back().engineer,"physical engineer assignment");auto plain=fixture(card,false);act(plain,1,{Intent::Project,region,0,200,60});test(w.projects().back().due<plain.projects().back().due,"engineer improves productivity without removing material cost");}
 if(card==6||card==11){int candidates=0;for(uint64_t id=1;id<=256;++id)candidates+=w.person(id).candidate;test(candidates==(card==6?3:2),"existing applicants not new people");test(w.count()==256,"no duplicated persons");std::vector<uint64_t> applicants;for(uint64_t id=1;id<=256;++id)if(w.person(id).candidate)applicants.push_back(id);for(auto id:applicants)act(w,id,{Intent::Work,w.person(id).region,0,0,30});std::vector<int> employed_before_appointment;for(auto&v:w.view().provinces)employed_before_appointment.push_back(v.employed);act(w,1,w.candidates(1)[15]);uint64_t hired=0;for(uint64_t id=1;id<=256;++id)if(w.person(id).hired_by==1)hired=id;test(hired>0&&w.person(hired).family==Family::Governance&&!w.person(hired).taxing_authority,"funded advisor role with restricted authority");test(w.person(hired).job==-1&&w.person(hired).busy_until==0&&w.person(hired).school_days==0,"appointment clears prior work fields");test(w.view().provinces[w.person(hired).region].employed==employed_before_appointment[size_t(w.person(hired).region)]-1,"appointment clears the selected worker counter");auto notice_before=w.fingerprint();test(!w.execute({hired,w.person(hired).decisions+1,{Intent::Resign,w.person(hired).region,0,0}}).success&&w.fingerprint()==notice_before,"advisor cannot resign before notice");w.advance(30);act(w,hired,w.candidates(hired)[31]);test(w.person(hired).family==Family::Civilian,"advisor can resign");if(card==6){Realm failed=fixture(6);int fr=failed.person(1).region;act(failed,1,failed.candidates(1)[15]);uint64_t unpaid=0;for(uint64_t id=1;id<=256;++id)if(failed.person(id).hired_by==1)unpaid=id;test(unpaid>0,"office salary fixture");failed.advance(29);test(failed.view().provinces[fr].treasury>0,"salary fixture treasury remains funded before drain");act(failed,1,{Intent::Aid,fr,0,failed.view().provinces[fr].treasury});test(failed.view().provinces[fr].treasury==0,"salary fixture treasury drained");failed.advance();bool failed_event=false;for(auto&f:failed.view(unpaid).facts)if(f.kind==110)failed_event=true;test(failed_event&&!failed.person(unpaid).office&&failed.person(unpaid).hired_by==0&&failed.person(unpaid).family==Family::Civilian,"unpaid office salary ends the appointment");test(failed.person(unpaid).salary_due==30&&failed.person(unpaid).office_notice==30,"salary failure leaves timers stale");}}
 if(card==7){act(w,1,w.candidates(1)[13]);act(w,1,w.candidates(1)[13]);test(w.investigations().size()==2&&w.mask(1)[13]==0,"two simultaneous investigations");}
 if(card==8){auto pool=w.royal_funds()[1];auto treasury=w.view().provinces[region].treasury;act(w,1,{Intent::Project,region,0,200,60});auto match=std::min<int64_t>(pool,100);test(w.royal_funds()[1]==pool-match&&w.view().provinces[region].treasury==treasury-200+match,"restricted half matching");auto remaining=w.royal_funds()[1];act(w,1,{Intent::Aid,region,0,1});test(w.royal_funds()[1]==remaining,"relief cannot spend restricted fund");}
 if(card==9){act(w,1,w.candidates(1)[21]);act(w,2,w.candidates(2)[28]);roundtrip(w);act(w,3,w.candidates(3)[29]);test(w.projects().empty()&&w.balances()[8]==0,"joint rejection refunds escrow and makes no fake project");act(w,1,w.candidates(1)[21]);for(uint64_t id:{2,3,4})act(w,id,w.candidates(id)[28]);test(w.projects().size()==3,"three independent funded acceptances");}
 test(w.total_money()==total,"augment money conserved after opening");roundtrip(w);
}
std::cout<<"COURT TESTS: "<<n<<" checks passed\n";return 0;}catch(const std::exception&e){std::cerr<<"FAIL after "<<n<<": "<<e.what()<<'\n';return 1;}}
